        source_a: &crate::CircuitTaskSourceInputV1,
        config_a: &codex_hepta_neuron::CellGenerationConfigV2,
        credentials: &'a material::Credentials,
    ) -> anyhow::Result<Self> {
        OriginalCellQ24MaterialCommandReceiptV1::require_original_dataset_context(dataset, material)?;
        anyhow::ensure!(material.initial.receipts.is_empty() && dataset.snapshot().receipts.len() == 2);
